/*
 * STM32F746G-DISCO Potentiometer + PWM LED
 * Potentiometer wiper on A0 (PA0, ADC3_IN0)
 * LED on D5 (PI0) with PWM brightness control
 * Note: STM32 uses 12-bit ADC (0-4095)
 */

int potPin = A0;    // A0 = PA0
int ledPin = 5;     // D5 = PI0 (PWM)
int potValue = 0;

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("STM32F746 potentiometer + PWM LED");
}

void loop() {
  potValue = analogRead(potPin);

  // Map 12-bit ADC (0-4095) to 8-bit PWM (0-255)
  int brightness = map(potValue, 0, 4095, 0, 255);
  analogWrite(ledPin, brightness);

  Serial.print("ADC: ");
  Serial.print(potValue);
  Serial.print(" | PWM: ");
  Serial.println(brightness);

  delay(100);
}
